{
  "metric": "daily yellow taxi trip count",
  "target_window": "2024-12-21 (Saturday)",
  "baseline_window": "2024-12-07, 2024-12-14, 2024-12-28 (other Saturdays in December 2024)",
  "hypotheses": [
    {
      "id": "H0",
      "kind": "metric",
      "statement": "Total yellow taxi trips on 2024-12-21 were lower than the average of the other three Saturdays in December 2024.",
      "support_if": "Trips on 2024-12-21 < average trips on 2024-12-07, 2024-12-14, 2024-12-28 by a meaningful margin (e.g., >5-10%).",
      "refute_if": "Trips on 2024-12-21 are roughly equal to or higher than the baseline Saturday average."
    },
    {
      "id": "H1",
      "kind": "weather",
      "statement": "Snowfall on 2024-12-21 suppressed taxi demand relative to other December Saturdays with no snow.",
      "support_if": "snow_mm > 0 on 2024-12-21 and snow_mm = 0 on all baseline Saturdays; trip count on 2024-12-21 is lower.",
      "refute_if": "No snow on 2024-12-21, or snow also occurred on baseline Saturdays, or trips did not drop despite snow."
    },
    {
      "id": "H2",
      "kind": "holiday",
      "statement": "A holiday on or near 2024-12-21 (e.g., Christmas week) altered travel patterns vs. other Saturdays.",
      "support_if": "A federal or state holiday falls on 2024-12-21 or the adjacent Friday/Monday, and baseline Saturdays have no nearby holidays.",
      "refute_if": "No holidays near 2024-12-21, or holidays also near baseline Saturdays."
    },
    {
      "id": "H3",
      "kind": "day_of_week",
      "statement": "The target day is a Saturday, same as baseline, so day-of-week is controlled; this hypothesis checks for any residual weekday effect (e.g., if baseline included non-Saturdays by mistake).",
      "support_if": "All comparison days are Saturdays (d_day_name = 'Saturday').",
      "refute_if": "Any comparison day is not a Saturday."
    },
    {
      "id": "H4",
      "kind": "fare_mix",
      "statement": "The mix of fare amounts (avg_total_amount) shifted on 2024-12-21, indicating a change in trip types (e.g., fewer short trips, more long trips or vice versa) that could correlate with weather.",
      "support_if": "avg_total_amount on 2024-12-21 differs significantly from baseline Saturday average.",
      "refute_if": "avg_total_amount on 2024-12-21 is similar to baseline average."
    },
    {
      "id": "H5",
      "kind": "zone_mix",
      "statement": "The geographic distribution of trips (by borough/zone) changed on 2024-12-21 due to snow, e.g., fewer trips to/from outer boroughs.",
      "support_if": "Trip counts by borough on 2024-12-21 show a different distribution vs. baseline Saturdays (requires zone-level data).",
      "refute_if": "Borough distribution is similar, or zone data not available at daily grain."
    },
    {
      "id": "H6",
      "kind": "data_quality",
      "statement": "Missing or incomplete trip data on 2024-12-21 (e.g., due to system outage during snowstorm) artificially lowers the count.",
      "support_if": "Trip count on 2024-12-21 is implausibly low (e.g., near zero) or metadata indicates data gaps.",
      "refute_if": "Trip count is plausible and consistent with expected range; no data quality flags."
    }
  ],
  "queries": [
    {
      "hypothesis_id": "H0",
      "purpose": "Get daily trip counts for all Saturdays in December 2024 to compute target vs. baseline average.",
      "tables": ["whybot.yellow_daily"]
    },
    {
      "hypothesis_id": "H1",
      "purpose": "Get snowfall (snow_mm) for each Saturday in December 2024 to compare 2024-12-21 vs. others.",
      "tables": ["whybot.nyc_weather_daily"]
    },
    {
      "hypothesis_id": "H2",
      "purpose": "Check for US holidays on or near each Saturday in December 2024 (target and baseline).",
      "tables": ["whybot.us_holidays"]
    },
    {
      "hypothesis_id": "H3",
      "purpose": "Confirm all comparison dates are Saturdays using calendar dimension.",
      "tables": ["TPCDS_DB.date_dim"]
    },
    {
      "hypothesis_id": "H4",
      "purpose": "Get avg_total_amount for each Saturday in December 2024 to assess fare mix changes.",
      "tables": ["whybot.yellow_daily"]
    },
    {
      "hypothesis_id": "H5",
      "purpose": "Assess if zone-level trip data is available at daily grain for December 2024 Saturdays (likely not in yellow_daily; this query checks feasibility).",
      "tables": ["NY_TAXI.taxi_zones"]
    },
    {
      "hypothesis_id": "H6",
      "purpose": "Check for data quality issues on 2024-12-21 by verifying trip count is non-zero and within plausible range vs. recent days.",
      "tables": ["whybot.yellow_daily"]
    }
  ],
  "rationale": "The plan quantifies the trip count difference (H0) and tests five competing explanations: weather (H1 - snow), holiday (H2), day-of-week control (H3), fare mix shift (H4), zone mix shift (H5 - limited by daily grain), and data quality (H6). Each hypothesis has a dedicated query using only catalog tables. The baseline uses the other three Saturdays in Dec 2024 for a like-for-like weekday comparison. Zone mix (H5) is included but likely not testable at daily level with current tables; query checks zone table existence. Data quality (H6) uses the same yellow_daily table to verify plausibility."
}

{
  "sql": "SELECT trip_date, trips, date_format(trip_date,'EEEE') AS weekday_name FROM whybot.yellow_daily WHERE dayofweek(trip_date) = 7 AND trip_date >= DATE '2024-12-01' AND trip_date <= DATE '2024-12-31' ORDER BY trip_date",
  "tables_used": ["whybot.yellow_daily"],
  "note": "Returns one row per Saturday in December 2024 ordered by date. weekday_name is Sunday..Saturday for downstream conditional aggregation to compute target vs baseline average."
}

{
  "sql": "SELECT trip_date, avg_total_amount FROM whybot.yellow_daily WHERE dayofweek(trip_date) = 7 AND month(trip_date) = 12 AND year(trip_date) = 2024 ORDER BY trip_date",
  "tables_used": ["whybot.yellow_daily"],
  "note": "Returns one row per Saturday in December 2024 with avg_total_amount to compare fare mix against the snowfall date of 2024-12-21."
}

